#!/usr/bin/env node
// Kysely types from the migrated database (R0.6, ADR 0005).
//
// Mechanism: kysely-codegen introspects the database that DATABASE_URL names and
// writes one TypeScript interface per table into packages/contracts/src/db.generated.ts.
// With --check the types are written to a temporary file and compared with the
// committed one, so the contracts job fails when a migration changed the schema and
// the generated file was not regenerated (A1 section 3: a contract change is always a
// visible diff). DATABASE_URL is read from the environment, else from .env at the
// repository root. Node and the workspace's kysely-codegen are the only requirements.

import { spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const TARGET = join(repoRoot, 'packages', 'contracts', 'src', 'db.generated.ts');
const TARGET_RELATIVE = 'packages/contracts/src/db.generated.ts';
const HEADER = [
  '// Generated by `just codegen` from the migrated database (R0.6, ADR 0005).',
  '// Do not edit by hand: change a migration under db/migrations and regenerate.',
  '// `just codegen-check` (the contracts job) fails when this file is stale.',
  '',
].join('\n');

function loadDotEnv() {
  const path = join(repoRoot, '.env');
  if (!existsSync(path)) return {};
  const out = {};
  for (const line of readFileSync(path, 'utf8').split(/\r?\n/)) {
    if (!line || line.startsWith('#') || !line.includes('=')) continue;
    const i = line.indexOf('=');
    out[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  return out;
}

function databaseUrl() {
  const fromEnv = process.env.DATABASE_URL;
  if (fromEnv && fromEnv.trim() !== '') return fromEnv.trim();
  const fromFile = loadDotEnv().DATABASE_URL;
  if (fromFile) return fromFile;
  console.error('codegen: DATABASE_URL is not set and .env has none; run the migrations first (just db-migrate)');
  process.exit(2);
}

function generate(outFile, url) {
  // The URL travels in the environment, never on the command line, and the command is one
  // string so pnpm's .cmd shim resolves on Windows without passing arguments through a shell.
  if (/["\r\n]/.test(outFile)) {
    console.error('codegen: the temporary path contains a quote or newline');
    process.exit(2);
  }
  const command = `pnpm exec kysely-codegen --dialect postgres --out-file "${outFile}" --log-level warn`;
  const result = spawnSync(command, {
    cwd: repoRoot,
    encoding: 'utf8',
    shell: true,
    windowsHide: true,
    env: { ...process.env, DATABASE_URL: url },
  });
  if (result.error) {
    console.error(`codegen: could not run pnpm: ${result.error.message}`);
    process.exit(2);
  }
  if (result.status !== 0) {
    console.error(`codegen: kysely-codegen exited ${result.status}\n${result.stderr}`);
    process.exit(2);
  }
  const body = readFileSync(outFile, 'utf8').replace(/\r\n/g, '\n');
  return `${HEADER}${body}`;
}

function main(argv) {
  const check = argv.includes('--check');
  const url = databaseUrl();
  const tempDir = mkdtempSync(join(tmpdir(), 'codegen-'));
  const tempFile = join(tempDir, 'db.generated.ts');
  try {
    const generated = generate(tempFile, url);
    if (!check) {
      writeFileSync(TARGET, generated, 'utf8');
      console.log(`codegen: wrote ${TARGET_RELATIVE}`);
      return 0;
    }
    if (!existsSync(TARGET)) {
      console.error(`codegen: ${TARGET_RELATIVE} is missing; run just codegen and commit it`);
      return 1;
    }
    const committed = readFileSync(TARGET, 'utf8').replace(/\r\n/g, '\n');
    if (committed !== generated) {
      console.error(`codegen: ${TARGET_RELATIVE} is stale; run just codegen and commit the result`);
      return 1;
    }
    console.log(`codegen: ${TARGET_RELATIVE} is up to date`);
    return 0;
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
}

process.exitCode = main(process.argv.slice(2));
